"""Emission compliance tests for tests (auto-generated by pact)."""

from tests.tests import Tests


class TestEmissionCompliance:
    """Verify tests emits structured events correctly."""

    def _make_handler(self):
        events = []
        return events, lambda event: events.append(event)

    def test_configureVitestSetup_emits_events(self):
        """Method configureVitestSetup emits invoked and completed events."""
        events, handler = self._make_handler()
        obj = Tests(event_handler=handler)
        try:
            obj.configureVitestSetup()
        except (TypeError, Exception):
            pass
        invoked = [e for e in events if e.get("event") == "invoked"]
        completed = [e for e in events if e.get("event") in ("completed", "error")]
        assert len(invoked) >= 1, 'No invoked event for configureVitestSetup'
        assert len(completed) >= 1, 'No completed/error event for configureVitestSetup'
        assert invoked[0].get("pact_key") == "PACT:tests:configureVitestSetup"
        assert isinstance(invoked[0].get("input_classification"), list)

