    def test_pact_key_format(self):
        """All emitted events have correctly formatted PACT keys."""
        events, handler = self._make_handler()
        obj = Tests(event_handler=handler)
        try:
            obj.configureVitestSetup()
        except (TypeError, Exception):
            pass
        try:
            obj.assertToolDefListLength()
        except (TypeError, Exception):
            pass
        try:
            obj.assertSlugOrder()
        except (TypeError, Exception):
            pass
        try:
            obj.assertRequiredFieldsPerTool()
        except (TypeError, Exception):
            pass
        try:
            obj.assertKindexNoVideoUrl()
        except (TypeError, Exception):
            pass
        try:
            obj.assertAtLeastOneVideoUrl()
        except (TypeError, Exception):
            pass
        try:
            obj.renderWithProviders()
        except (TypeError, Exception):
            pass
        try:
            obj.smokeTestComponentRender()
        except (TypeError, Exception):
            pass
        try:
            obj.executeTestSuite()
        except (TypeError, Exception):
            pass
        for event in events:
            key = event.get("pact_key", "")
            assert key.startswith("PACT:tests:"), f"Bad pact_key: {key}"

